// ============================================================================
// 3. 2D OBB SEPARATING AXIS THEOREM (SAT) COLLISION & CORE ENGINE
// ============================================================================
function createObbVertices(cx, cy, halfW, halfL, dir) {
  const fx = dir.dx, fy = dir.dy;
  const lx = dir.ndx, ly = dir.ndy;
  return [
    { x: cx + fx * halfL + lx * halfW, y: cy + fy * halfL + ly * halfW },
    { x: cx + fx * halfL - lx * halfW, y: cy + fy * halfL - ly * halfW },
    { x: cx - fx * halfL - lx * halfW, y: cy - fy * halfL - ly * halfW },
    { x: cx - fx * halfL + lx * halfW, y: cy - fy * halfL + ly * halfW }
  ];
}

function polygonsIntersect(vertsA, vertsB, tol = 1e-5) {
  const checkAxes = (p1, p2) => {
    for (let i = 0; i < p1.length; i++) {
      const v1 = p1[i];
      const v2 = p1[(i + 1) % p1.length];
      const ex = v2.x - v1.x, ey = v2.y - v1.y;
      const len = Math.hypot(ex, ey) || 1;
      const nx = -ey / len, ny = ex / len;

      let min1 = Infinity, max1 = -Infinity;
      for (const v of p1) {
        const d = v.x * nx + v.y * ny;
        if (d < min1) min1 = d;
        if (d > max1) max1 = d;
      }
      let min2 = Infinity, max2 = -Infinity;
      for (const v of p2) {
        const d = v.x * nx + v.y * ny;
        if (d < min2) min2 = d;
        if (d > max2) max2 = d;
      }
      if (max1 < min2 + tol || max2 < min1 + tol) return false;
    }
    return true;
  };
  return checkAxes(vertsA, vertsB) && checkAxes(vertsB, vertsA);
}

function checkRaycast(state, vehicleId) {
  const v = state.vehicles[vehicleId];
  if (!v || v.state !== "PARKED" || v.isMystery) {
    return { isClear: false, firstBlocker: null, exitDistance: 0, collisionDistance: null };
  }

  const dx = v.direction.dx, dy = v.direction.dy;
  const frontX = v.anchorX + dx * (v.length / 2);
  const frontY = v.anchorY + dy * (v.length / 2);

  const tx = dx > 1e-5 ? (state.gridWidth - frontX) / dx : (dx < -1e-5 ? (0 - frontX) / dx : Infinity);
  const ty = dy > 1e-5 ? (state.gridHeight - frontY) / dy : (dy < -1e-5 ? (0 - frontY) / dy : Infinity);
  const exitDist = Math.max(0, Math.min(tx, ty)) + v.length + 0.5;

  const eps = v.direction.diag ? 0.08 : 0.0;
  const corrW = Math.max(0.1, v.width - eps) * 0.92;
  const corrCenterX = frontX + dx * (exitDist / 2);
  const corrCenterY = frontY + dy * (exitDist / 2);
  const rayPoly = createObbVertices(corrCenterX, corrCenterY, corrW / 2, exitDist / 2, v.direction);

  let firstBlocker = null;
  let minDistance = Infinity;

  Object.values(state.vehicles).forEach(other => {
    if (other.id === vehicleId || other.state !== "PARKED") return;
    const otherPoly = createObbVertices(
      other.anchorX,
      other.anchorY,
      (other.width * 0.95) / 2,
      (other.length * 0.95) / 2,
      other.direction
    );
    if (polygonsIntersect(rayPoly, otherPoly)) {
      const dist = (other.anchorX - frontX) * dx + (other.anchorY - frontY) * dy;
      if (dist < minDistance) {
        minDistance = dist;
        firstBlocker = other;
      }
    }
  });

  return {
    isClear: firstBlocker === null,
    firstBlocker,
    exitDistance: exitDist,
    collisionDistance: firstBlocker ? Math.max(0.15, minDistance - (firstBlocker.width * 0.45)) : null
  };
}

function getActiveBoardingColor(vehicle) {
  if (vehicle.secondaryColor && vehicle.seatedCount >= 4) {
    return vehicle.secondaryColor;
  }
  return vehicle.color;
}

function isTunnelSpawnZoneClear(state, tunnel) {
  const spawnX = tunnel.anchorX + tunnel.exitDirection.dx * (1.5 * 0.76);
  const spawnY = tunnel.anchorY + tunnel.exitDirection.dy * (1.5 * 0.76);
  const spawnPoly = createObbVertices(spawnX, spawnY, (1.0 * 0.76 * 0.95) / 2, (2.0 * 0.76 * 0.95) / 2, tunnel.exitDirection);
  return Object.values(state.vehicles).every(v => {
    if (v.state !== "PARKED") return true;
    const pPoly = createObbVertices(v.anchorX, v.anchorY, (v.width * 0.95) / 2, (v.length * 0.95) / 2, v.direction);
    return !polygonsIntersect(spawnPoly, pPoly);
  });
}

