const STORAGE_KEY = "transit_krama_bfp_profile";

const ICON_ASSETS = {
  choice2: {
    label: "Choice 2 (Primary)",
    banner: "data:image/jpeg;base64,",
    thumb: "data:image/jpeg;base64,"
  },
  choice1: {
    label: "Choice 1 (Alternative)",
    banner: "data:image/jpeg;base64,",
    thumb: "data:image/jpeg;base64,"
  }
};

function applyIconChoice(choiceKey, notifyAndroid = false) {
  const key = (choiceKey === "choice1") ? "choice1" : "choice2";
  if (profile && profile.settings) profile.settings.iconChoice = key;
  if (typeof document === "undefined") return;

  const t2 = document.getElementById("imgIconChoice2Thumb");
  const t1 = document.getElementById("imgIconChoice1Thumb");
  if (t2 && !t2.getAttribute("src")) t2.src = ICON_ASSETS.choice2.thumb;
  if (t1 && !t1.getAttribute("src")) t1.src = ICON_ASSETS.choice1.thumb;

  const heroImg = document.getElementById("heroBannerImg");
  if (heroImg) heroImg.src = ICON_ASSETS[key].banner;

  const badge = document.getElementById("activeIconBadge");
  if (badge) badge.textContent = ICON_ASSETS[key].label;

  const b2 = document.getElementById("btnIconChoice2");
  const b1 = document.getElementById("btnIconChoice1");
  if (b2 && b1) {
    if (key === "choice2") {
      b2.className = "btn-3d rounded-xl p-2 border-2 border-amber-400 bg-slate-900/90 flex items-center gap-2 text-left transition";
      b1.className = "btn-3d rounded-xl p-2 border border-slate-700 bg-slate-900/50 flex items-center gap-2 text-left transition";
    } else {
      b1.className = "btn-3d rounded-xl p-2 border-2 border-amber-400 bg-slate-900/90 flex items-center gap-2 text-left transition";
      b2.className = "btn-3d rounded-xl p-2 border border-slate-700 bg-slate-900/50 flex items-center gap-2 text-left transition";
    }
  }

  let link = document.querySelector("link[rel~='icon']");
  if (!link) {
    link = document.createElement("link");
    link.rel = "icon";
    document.head.appendChild(link);
  }
  link.href = ICON_ASSETS[key].thumb;

  if (notifyAndroid && typeof window !== "undefined" && window.AndroidBridge && window.AndroidBridge.setAppIcon) {
    try { window.AndroidBridge.setAppIcon(key); } catch (e) {}
  }
}


let profile = {
  currentLevel: 1,
  maxUnlockedLevel: 1,
  gold: 80,
  winStreak: 0,
  bestStreak: 0,
  settings: {
    soundEnabled: true,
    hapticsEnabled: true,
    colorblindMode: false,
    nightMode: false,
    autoFastForward: true,
    iconChoice: "choice2"
  },
  savedMidLevelState: null
};

function loadProfile() {
  try {
    if (typeof localStorage !== "undefined") {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        profile = Object.assign({}, profile, parsed);
        profile.settings = Object.assign({
          soundEnabled: true,
          hapticsEnabled: true,
          colorblindMode: false,
          nightMode: false,
          autoFastForward: true
        }, parsed.settings || {});
      }
    }
  } catch (e) {}
  syncSettingsToEngine();
}

function saveProfile() {
  try {
    if (typeof localStorage !== "undefined") {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profile));
    }
  } catch (e) {}
}

function syncSettingsToEngine() {
  audio.enabled = profile.settings.soundEnabled;
  audio.hapticsEnabled = profile.settings.hapticsEnabled;
  if (typeof document === "undefined") return;
  document.getElementById("chkSound").checked = profile.settings.soundEnabled;
  document.getElementById("chkHaptics").checked = profile.settings.hapticsEnabled;
  document.getElementById("chkColorblind").checked = profile.settings.colorblindMode;
  document.getElementById("chkNightMode").checked = profile.settings.nightMode;
  document.getElementById("chkAutoFast").checked = profile.settings.autoFastForward;
  const nightIcon = profile.settings.nightMode ? "🌙" : "☀️";
  document.getElementById("hudNightIcon").textContent = nightIcon;
  document.getElementById("homeNightIcon").textContent = nightIcon;
  applyIconChoice(profile.settings.iconChoice || "choice2", false);
}

