// ============================================================================
// 5. STADIUM-OVAL CROWD LOOP GEOMETRY & ANGLED WAITING BAYS (-20 DEG)
// ============================================================================
const BAY_TILT_DEG = 344; // -18 degrees counter-clockwise (\)

function getBayCenter(bayIndex, totalBays, bounds) {
  const cx = (bounds.left + bounds.right) / 2;
  const usableW = Math.max((bounds.right - bounds.left) + 2.85, 10.08);
  const leftEdge = cx - usableW / 2;
  const spacing = usableW / Math.max(1, totalBays);
  const bx = leftEdge + bayIndex * spacing + spacing / 2;
  // Vertically centered between roadTopY (parkBottomY - 0.15 = roadY + 1.21) and roadBotY (roadY - 1.35)
  const by = bounds.roadY - 0.06;
  return { x: bx, y: by };
}

// Stadium-Oval Track Geometry (Exact Bus Fever Party Oval + Top-Right Feeder Chute):
// Center (cx, cy), straight half-length `straightHalf`, semicircle radius `curveR`.
function getStadiumOvalMetrics(bounds) {
  const cx = (bounds.left + bounds.right) / 2;
  const cy = bounds.parkBottomY + 3.18;
  const curveR = 1.74;
  const straightHalf = Math.max(1.24, (bounds.right - bounds.left) * 0.16);
  return { cx, cy, curveR, straightHalf, trackWidth: 1.84 };
}

function getOvalLoopExitWorldPos(bounds = islandBounds) {
  const m = getStadiumOvalMetrics(bounds);
  return { x: m.cx, y: m.cy - m.curveR - 0.15 };
}

// Continuous uniform-spacing queue path around the Stadium-Oval Track + Top-Right Feeder Chute:
// slot = 0 is at the Bottom-Center Boarding Gate.
// As slot increases (0 -> 1 -> 2 -> ...):
// - Slots 0..5: Bottom-right straight & right lower curve
// - Slots 6..13: Right semicircle & top-right curve
// - Slots 14..22: Top straight & left semicircle (wrapping around the full stadium oval at level start!)
// - Slots 23+: Top-Right Feeder Chute extending to the upper-right park corner!
// Wait: to make the crowd flow continuously without any jump between the oval and the feeder chute,
// let's trace the continuous smooth path from the Bottom-Center Gate backwards:
// Wait: in Bus Fever Party! (`4x9CT56hTdE` & `MXMpkLLIomQ`):
// - The incoming crowd flows from the **Top-Right Feeder** -> around the **Oval Loop** -> to the **Bottom-Center Gate**!
// - And any recirculating crowd flows from the **Bottom-Center Gate** -> **Bottom-Left** -> up the **Left Semicircle** -> across the **Top Straight** -> merging at the **Top-Right**!
const RING_SLOTS = 18;           // 18 uniform shoulder-to-shoulder slots around 100% of the 360-degree Stadium-Oval Roundabout
const MAX_ROUNDABOUT_ROWS = 18;  // Roundabout is 100% FULL (all 18 slots = 72 people); all remaining rows queue continuously on the Above Road!
const JUNCTION_SLOT = 10.0;      // Top-Right Merge Junction (right end of Top Straight) where the Above Feeder Road merges seamlessly
const MIN_ROW_GAP = 1.0;         // 1.0 slot (~0.52 world units) tight shoulder-to-shoulder spacing around the 18-slot Roundabout
const CROWD_WALK_SPEED = 2.8;    // 100% CONSTANT walking speed (slots/sec) — never increases as people sit in vehicles!

let roundaboutRingPoints = [];
let feederChutePoints = [];
let roundaboutSlip = 0;
let feederWalkOffset = 0;
let openSlotDebt = 0;

function buildRoundaboutAndFeederPoints(bounds) {
  const m = getStadiumOvalMetrics(bounds);

  const makePt = (x, y, walkDx, walkDy) => {
    const len = Math.hypot(walkDx, walkDy) || 1;
    const tx = walkDx / len, ty = walkDy / len;
    const nx = -ty, ny = tx;
    const facingDeg = (Math.atan2(tx, ty) * 180) / Math.PI;
    return { x, y, tx, ty, nx, ny, facingDeg };
  };

  // A. Build Closed 360-Degree Stadium-Oval Polyline parameterized CLOCKWISE from Slot 0 (Bottom-Center Gate)
  //    so that DECREASING `p.pos -= CROWD_WALK_SPEED * dt` walks COUNTER-CLOCKWISE (exact MXMpkLLIomQ flow!):
  //    - Slot 11.2 (Top-Right Junction) -> Slot 8.0 (Top-Left) : walking LEFT across Top Straight
  //    - Slot 8.0 -> Slot 2.0 (Bottom-Left) : walking DOWN around Left Semicircle
  //    - Slot 2.0 -> Slot 0.0 (Bottom-Center Boarding Gate) : walking RIGHT along Bottom-Left Straight to Gate
  //    - Slot 20.0 -> Slot 18.0 (Bottom-Right) : walking RIGHT past Gate along Bottom-Right Straight
  //    - Slot 18.0 -> Slot 11.2 (Top-Right Junction) : walking UP around Right Semicircle back to Junction!
  const closedPoly = [];
  const segSteps = 24;
  const arcSteps = 48;

  // 1. Bottom-Left Straight: from Gate (m.cx, m.cy - m.curveR) LEFT to (m.cx - m.straightHalf, m.cy - m.curveR)
  for (let i = 0; i < segSteps; i++) {
    const t = i / segSteps;
    closedPoly.push({
      x: m.cx - t * m.straightHalf,
      y: m.cy - m.curveR
    });
  }
  // 2. Left Semicircle: from -90 deg (bottom-left) clockwise through -180 deg (left) to -270 deg (+90 deg, top-left)
  for (let i = 0; i < arcSteps; i++) {
    const t = i / arcSteps;
    const ang = (-Math.PI / 2) - t * Math.PI;
    closedPoly.push({
      x: (m.cx - m.straightHalf) + Math.cos(ang) * m.curveR,
      y: m.cy + Math.sin(ang) * m.curveR
    });
  }
  // 3. Top Straight: from (m.cx - m.straightHalf, m.cy + m.curveR) RIGHT to (m.cx + m.straightHalf, m.cy + m.curveR)
  for (let i = 0; i < segSteps * 2; i++) {
    const t = i / (segSteps * 2);
    closedPoly.push({
      x: (m.cx - m.straightHalf) + t * (m.straightHalf * 2.0),
      y: m.cy + m.curveR
    });
  }
  // 4. Right Semicircle: from +90 deg (top-right) clockwise through 0 deg (right) to -90 deg (bottom-right)
  for (let i = 0; i < arcSteps; i++) {
    const t = i / arcSteps;
    const ang = (Math.PI / 2) - t * Math.PI;
    closedPoly.push({
      x: (m.cx + m.straightHalf) + Math.cos(ang) * m.curveR,
      y: m.cy + Math.sin(ang) * m.curveR
    });
  }
  // 5. Bottom-Right Straight: from (m.cx + m.straightHalf, m.cy - m.curveR) LEFT back to Gate (m.cx, m.cy - m.curveR)
  for (let i = 0; i <= segSteps; i++) {
    const t = i / segSteps;
    closedPoly.push({
      x: (m.cx + m.straightHalf) - t * m.straightHalf,
      y: m.cy - m.curveR
    });
  }

  const cumLen = [0];
  for (let i = 1; i < closedPoly.length; i++) {
    const d = Math.hypot(closedPoly[i].x - closedPoly[i - 1].x, closedPoly[i].y - closedPoly[i - 1].y);
    cumLen.push(cumLen[i - 1] + d);
  }
  const totalLoopLen = cumLen[cumLen.length - 1];

  const ringPts = [];
  const sampleCount = RING_SLOTS * 8;
  for (let s = 0; s < sampleCount; s++) {
    const targetD = (s / sampleCount) * totalLoopLen;
    let seg = 0;
    while (seg < cumLen.length - 2 && cumLen[seg + 1] < targetD) seg++;
    const segLen = Math.max(1e-5, cumLen[seg + 1] - cumLen[seg]);
    const frac = (targetD - cumLen[seg]) / segLen;
    const p0 = closedPoly[seg];
    const p1 = closedPoly[seg + 1];
    const px = p0.x + (p1.x - p0.x) * frac;
    const py = p0.y + (p1.y - p0.y) * frac;
    // Walking direction is toward decreasing s (p0 - p1), which is COUNTER-CLOCKWISE!
    ringPts.push(makePt(px, py, p0.x - p1.x, p0.y - p1.y));
  }
  roundaboutRingPoints = ringPts;

  // B. Build Top-Right Feeder Road Points starting at JUNCTION_SLOT (11.2, right end of Top Straight)
  //    and extending diagonally up-right (+42 deg) so the Feeder Road is 100% centered under the crowd!
  const jPt = sampleRoundaboutRing(JUNCTION_SLOT);
  const chutePoly = [];
  const dirX = 0.56, dirY = 0.828;
  const slotWorldStride = totalLoopLen / RING_SLOTS;
  for (let i = 0; i <= 50; i++) {
    const dist = i === 0 ? 0 : (1.34 + (i - 1) * 1.0) * slotWorldStride;
    chutePoly.push({
      x: jPt.x + dirX * dist,
      y: jPt.y + dirY * dist
    });
  }
  const chutePts = [];
  for (let i = 0; i < chutePoly.length - 1; i++) {
    const p0 = chutePoly[i];
    const p1 = chutePoly[i + 1];
    chutePts.push(makePt(p0.x, p0.y, p0.x - p1.x, p0.y - p1.y));
  }
  feederChutePoints = chutePts;
}

function sampleRoundaboutRing(slotInRing) {
  if (roundaboutRingPoints.length === 0) {
    buildRoundaboutAndFeederPoints(islandBounds);
  }
  const N = roundaboutRingPoints.length;
  const norm = (((slotInRing / RING_SLOTS) % 1.0) + 1.0) % 1.0;
  const fIdx = norm * N;
  const i0 = Math.floor(fIdx) % N;
  const i1 = (i0 + 1) % N;
  const frac = fIdx - Math.floor(fIdx);
  const p0 = roundaboutRingPoints[i0];
  const p1 = roundaboutRingPoints[i1];
  return {
    x: p0.x + (p1.x - p0.x) * frac,
    y: p0.y + (p1.y - p0.y) * frac,
    nx: p0.nx + (p1.nx - p0.nx) * frac,
    ny: p0.ny + (p1.ny - p0.ny) * frac,
    facingDeg: p0.facingDeg
  };
}

function sampleFeederChute(chuteSlot) {
  if (feederChutePoints.length === 0) {
    buildRoundaboutAndFeederPoints(islandBounds);
  }
  const clamped = Math.max(0, Math.min(feederChutePoints.length - 1.001, chuteSlot));
  const i0 = Math.floor(clamped);
  const i1 = Math.min(feederChutePoints.length - 1, i0 + 1);
  const frac = clamped - i0;
  const p0 = feederChutePoints[i0];
  const p1 = feederChutePoints[i1];
  let nx = p0.nx + (p1.nx - p0.nx) * frac;
  let ny = p0.ny + (p1.ny - p0.ny) * frac;
  if (clamped < 1.2) {
    const jPt = sampleRoundaboutRing(JUNCTION_SLOT);
    const blend = Math.max(0, Math.min(1, 1.0 - clamped / 1.2));
    nx = nx * (1 - blend) + jPt.nx * blend;
    ny = ny * (1 - blend) + jPt.ny * blend;
    const nLen = Math.hypot(nx, ny) || 1;
    nx /= nLen;
    ny /= nLen;
  }
  return {
    x: p0.x + (p1.x - p0.x) * frac,
    y: p0.y + (p1.y - p0.y) * frac,
    nx,
    ny,
    facingDeg: p0.facingDeg
  };
}

// Initialize physical positions (`zone` and `pos`) for all rows in `levelState.passengerQueue`:
// - First 15 rows (0..14): packed shoulder-to-shoulder from Gate (0.0) -> Bottom-Left -> Left Semicircle -> Top Straight up to 10.08 (just below JUNCTION_SLOT = 11.2)!
// - Remaining rows (15+): packed shoulder-to-shoulder on the Top-Right Feeder Road starting at 0.72, 1.44, 2.16, ...
const FEEDER_WAIT_OFFSET = 1.0; // Keeps the first waiting Feeder row cleanly outside the Roundabout outer curb!

function initCrowdPhysicalPositions(queue) {
  let feederIdx = 0;
  for (let r = 0; r < queue.length; r++) {
    const p = queue[r];
    if (r < MAX_ROUNDABOUT_ROWS) {
      p.zone = "ROUNDABOUT";
      p.pos = r * MIN_ROW_GAP;
    } else {
      p.zone = "FEEDER";
      p.pos = FEEDER_WAIT_OFFSET + (feederIdx++) * MIN_ROW_GAP;
    }
    p.moveSpeed = 0;
    p.members = [0, 1, 2, 3].map(col => ({
      col,
      lag: 0,
      phaseOffset: col * 1.45 + r * 0.85
    }));
  }
}

function forwardRingDist(fromSlot, toAheadSlot) {
  return ((fromSlot - toAheadSlot) % RING_SLOTS + RING_SLOTS) % RING_SLOTS;
}

function generateWaypoints(vehicle, targetBayIndex, bounds, totalBays = TOTAL_BAY_SLOTS) {
  const start = { x: vehicle.anchorX, y: vehicle.anchorY };
  const dx = vehicle.direction.dx, dy = vehicle.direction.dy;
  const laneLeft = bounds.left - 0.95;
  const laneRight = bounds.right + 0.95;
  const laneBottom = bounds.bottom - 0.75;
  const feederRoadY = bounds.roadY - 1.05;

  const bayC = getBayParkedWorldPos(targetBayIndex, vehicle, bounds);

  let tMin = Infinity;
  if (dx > 0.001) {
    const t = (laneRight - start.x) / dx;
    if (t > 0 && t < tMin) tMin = t;
  } else if (dx < -0.001) {
    const t = (laneLeft - start.x) / dx;
    if (t > 0 && t < tMin) tMin = t;
  }
  if (dy > 0.001) {
    const t = (feederRoadY - start.y) / dy;
    if (t > 0 && t < tMin) tMin = t;
  } else if (dy < -0.001) {
    const t = (laneBottom - start.y) / dy;
    if (t > 0 && t < tMin) tMin = t;
  }

  const hitX = Math.max(laneLeft, Math.min(laneRight, start.x + dx * tMin));
  const hitY = Math.max(laneBottom, Math.min(feederRoadY, start.y + dy * tMin));
  const waypoints = [start, { x: hitX, y: hitY }];

  const hitTop = Math.abs(hitY - feederRoadY) <= 0.18;
  const hitBottom = Math.abs(hitY - laneBottom) <= 0.18;
  const hitLeft = Math.abs(hitX - laneLeft) <= 0.18;
  const hitRight = Math.abs(hitX - laneRight) <= 0.18;

  if (!hitTop) {
    const midX = (bounds.left + bounds.right) / 2;
    if (hitBottom) {
      const sideX = hitX < midX ? laneLeft : laneRight;
      waypoints.push({ x: sideX, y: laneBottom }, { x: sideX, y: feederRoadY });
    } else if (hitLeft) {
      waypoints.push({ x: laneLeft, y: feederRoadY });
    } else if (hitRight) {
      waypoints.push({ x: laneRight, y: feederRoadY });
    } else {
      const sideX = hitX < midX ? laneLeft : laneRight;
      waypoints.push({ x: sideX, y: hitY }, { x: sideX, y: feederRoadY });
    }
  }

  const approachX = bayC.x + 0.30;
  waypoints.push({ x: approachX, y: feederRoadY });
  waypoints.push(bayC);
  return waypoints;
}

function lerpAngle(cur, target, maxDelta) {
  let diff = (target - cur) % 360;
  if (diff < -180) diff += 360;
  if (diff > 180) diff -= 360;
  const delta = Math.max(-maxDelta, Math.min(maxDelta, diff));
  return (cur + delta + 360) % 360;
}

// ============================================================================
// 6. SIMULTANEOUS MULTI-VEHICLE DISPATCH & CIRCULATING OVAL CROWD BOARDING
// ============================================================================
function startLevel(levelId, resumedState = null) {
  resetAnimations();
  historyStack = [];
  isFastForward = false;

  if (resumedState) {
    levelState = JSON.parse(JSON.stringify(resumedState));
    Object.values(levelState.vehicles).forEach(v => {
      if (v.state === "EN_ROUTE") v.state = "IN_BAY";
      if (typeof v.subSeatedCount !== "number") v.subSeatedCount = v.seatedCount * CROWD_MULT;
    });
  } else {
    levelState = decodeLevel(levelId);
    profile.currentLevel = levelId;
    profile.savedMidLevelState = null;
    saveProfile();
  }

  islandBounds = computeIslandBounds(levelState);
  buildRoundaboutAndFeederPoints(islandBounds);
  initCrowdPhysicalPositions(levelState.passengerQueue);

  if (typeof document !== "undefined") {
    document.getElementById("homeScreen").classList.add("hidden");
    document.getElementById("homeScreen").classList.remove("flex");
    document.getElementById("gameScreen").classList.remove("hidden");
    document.getElementById("gameScreen").classList.add("flex");
    document.getElementById("victoryModal").classList.add("hidden");
    document.getElementById("rescueModal").classList.add("hidden");
    updateGameHud();
    resizeCanvas();
  }
}

function cloneState(st) {
  return JSON.parse(JSON.stringify(st));
}

function onVehicleTap(vehicleId) {
  if (levelState.status !== "PLAYING") return;
  const v = levelState.vehicles[vehicleId];
  if (!v || v.state !== "PARKED" || movingVehicles.has(vehicleId) || blockedBonks.has(vehicleId)) return;

  if (v.isMystery) {
    audio.playBlockedBump();
    audio.vibrate(40);
    vehicleWobbles.set(vehicleId, { elapsed: 0, duration: 0.35, axisX: 1, axisZ: 0, amp: 0.25 });
    floatingPopups.push({
      pos: { x: v.anchorX, y: v.anchorY },
      text: "?",
      color: "#FFC700",
      elapsed: 0,
      duration: 0.65
    });
    return;
  }

  const raycast = checkRaycast(levelState, vehicleId);
  if (!raycast.isClear) {
    // BUS FEVER PARTY LUNGE-AND-BONK PHYSICS!
    const fx = v.direction.dx, fy = v.direction.dy;
    const rawDist = raycast.collisionDistance !== null ? raycast.collisionDistance : 0.45;
    const lungeDist = Math.max(0.24, Math.min(1.65, rawDist));
    const targetPos = {
      x: v.anchorX + fx * lungeDist,
      y: v.anchorY + fy * lungeDist
    };
    const speed = 10.5;
    const lungeDur = Math.max(0.07, Math.min(0.20, lungeDist / speed));

    blockedBonks.set(vehicleId, {
      vehicleId,
      startPos: { x: v.anchorX, y: v.anchorY },
      targetPos,
      currentPos: { x: v.anchorX, y: v.anchorY },
      dir: v.direction,
      blockerId: raycast.firstBlocker ? raycast.firstBlocker.id : null,
      lungeDuration: lungeDur,
      returnDuration: lungeDur * 1.2,
      elapsed: 0,
      hitTriggered: false
    });
    return;
  }

  // SIMULTANEOUS MULTI-VEHICLE DISPATCH:
  // Pick the first unlocked bay that is not currently occupied or reserved
  const targetBay = levelState.waitingBays.find(b => b.isUnlocked && b.occupantVehicleId === null);
  if (!targetBay) {
    audio.playBlockedBump();
    audio.vibrate(60);
    checkDeadlockAndVictory();
    return;
  }

  if (movingVehicles.size === 0 && activeBoarders.length === 0) {
    historyStack.push(cloneState(levelState));
    if (historyStack.length > 35) historyStack.shift();
  }
  hintVehicleId = null;

  const preTapVehicle = cloneState(v);
  levelState.stepCounter += 1;
  levelState.dispatchedCount += 1;

  // Immediately free the parking stall (`EN_ROUTE`) and reserve the bay so the player can
  // tap 2, 3, 4+ vehicles in rapid succession without waiting!
  v.state = "EN_ROUTE";
  v.assignedBayIndex = targetBay.index;
  v.arrivalOrder = levelState.stepCounter;
  targetBay.occupantVehicleId = v.id;
  targetBay.state = "RESERVED";

  const occCount = levelState.waitingBays.filter(b => b.occupantVehicleId !== null).length;
  if (occCount > levelState.peakBaysOccupied) levelState.peakBaysOccupied = occCount;

  // Reveal adjacent mystery vehicles immediately
  Object.values(levelState.vehicles).forEach(other => {
    if (other.id !== v.id && other.state === "PARKED" && other.isMystery) {
      const dist = Math.hypot(other.anchorX - v.anchorX, other.anchorY - v.anchorY);
      const maxSpan = (v.length + other.length) / 2 + 1.8;
      if (dist <= maxSpan) {
        other.isMystery = false;
        vehicleWobbles.set(other.id, { elapsed: 0, duration: 0.40, axisX: 0, axisZ: 1, amp: 0.25 });
        particlePuffs.push({
          pos: { x: other.anchorX, y: other.anchorY },
          color: "#FFC700",
          elapsedTime: 0,
          duration: 0.34,
          maxRadius: 22
        });
      }
    }
  });

  // Check Tunnel Spawning immediately
  levelState.tunnels.forEach(tunnel => {
    if (tunnel.spawnQueue.length > 0 && isTunnelSpawnZoneClear(levelState, tunnel)) {
      const nextCar = tunnel.spawnQueue.shift();
      nextCar.anchorX = tunnel.anchorX + tunnel.exitDirection.dx * (1.5 * 0.76);
      nextCar.anchorY = tunnel.anchorY + tunnel.exitDirection.dy * (1.5 * 0.76);
      nextCar.direction = tunnel.exitDirection;
      nextCar.state = "PARKED";
      levelState.vehicles[nextCar.id] = nextCar;
      vehicleWobbles.set(nextCar.id, { elapsed: 0, duration: 0.38, axisX: 1, axisZ: 0, amp: 0.22 });
      particlePuffs.push({
        pos: { x: nextCar.anchorX, y: nextCar.anchorY },
        color: "#FFFFFF",
        elapsedTime: 0,
        duration: 0.30,
        maxRadius: 20
      });
    }
  });

  audio.playHornThump();
  audio.vibrate(20);

  const waypoints = generateWaypoints(preTapVehicle, targetBay.index, islandBounds, TOTAL_BAY_SLOTS);
  movingVehicles.set(preTapVehicle.id, {
    vehicleId: preTapVehicle.id,
    initialVehicle: preTapVehicle,
    waypoints,
    targetBayIndex: targetBay.index,
    currentPos: { x: waypoints[0].x, y: waypoints[0].y },
    currentHeading: preTapVehicle.direction.deg,
    waypointIdx: 1,
    stage: "PULL_OUT",
    bounceScale: 1.0,
    steeringRoll: 0,
    pauseTimer: 0,
    isDeparting: false,
    exhaustTimer: 0
  });

  const parkedRemaining = Object.values(levelState.vehicles).filter(veh => veh.state === "PARKED").length;
  const tunnelRemaining = levelState.tunnels.reduce((a, t) => a + t.spawnQueue.length, 0);
  if (parkedRemaining === 0 && tunnelRemaining === 0 && profile.settings.autoFastForward) {
    isFastForward = true;
  }

  profile.savedMidLevelState = cloneState(levelState);
  saveProfile();
  updateGameHud();
}

// ============================================================================
// REAL-TIME OVAL LOOP CROWD BOARDING & CLOCKWISE LEFT-LOOP RECIRCULATION
// ============================================================================
// In Bus Fever Party! (`4x9CT56hTdE` & `MXMpkLLIomQ`):
// 1. Only buses that have PHYSICALLY ARRIVED in their waiting bay (`v.state === "IN_BAY"`) board passengers.
// 2. If the front row (`passengerQueue[0]`) matches a parked bus in a bay, 4 runners sprint from the
//    oval loop exit into that bus!
// 3. What if a bus is parked in a bay (say Yellow), and `passengerQueue[0]` is Red (no Red bus in bays),
//    while Yellow passengers exist further back in `passengerQueue` (within the active oval loop window)?
//    The non-matching front row (`Red`) does NOT freeze the loop—it walks clockwise around the left return
//    loop of the oval track and merges back behind the active loop window, allowing the Yellow row to
//    reach the bottom-center gate and board the waiting Yellow bus!
function stepRealtimeBoarding(effDt) {
  boarderSpawnCooldown = Math.max(0, boarderSpawnCooldown - effDt);
  const queue = levelState.passengerQueue;
  if (queue.length === 0) return;

  if (typeof queue[0].pos !== "number") {
    initCrowdPhysicalPositions(queue);
  }

  // Find all buses physically parked in an angled waiting bay right now with open seats
  const parkedBays = Object.values(levelState.vehicles).filter(v => {
    if (v.state !== "IN_BAY") return false;
    if (v.seatedCount >= v.capacity) return false;
    const mAnim = movingVehicles.get(v.id);
    if (mAnim && (mAnim.stage !== "PARKED_IN_BAY" || mAnim.isDeparting)) return false;
    return true;
  });

  // 1. Check if any ROUNDABOUT row is currently in the Bottom-Center Boarding Gate zone (pos <= 0.55 or pos >= RING_SLOTS - 0.35)
  //    and matches a parked bus in the waiting bays!
  if (parkedBays.length > 0 && boarderSpawnCooldown <= 0) {
    let gateRowIdx = -1;
    let bestGateDist = Infinity;
    for (let i = 0; i < queue.length; i++) {
      const p = queue[i];
      if (p.zone !== "ROUNDABOUT") continue;
      const distToGate = Math.min(p.pos, RING_SLOTS - p.pos);
      if (distToGate <= 0.55 && distToGate < bestGateDist) {
        const hasBus = parkedBays.some(v => getActiveBoardingColor(v) === p.color);
        if (hasBus) {
          bestGateDist = distToGate;
          gateRowIdx = i;
        }
      }
    }

    if (gateRowIdx !== -1) {
      const passenger = queue.splice(gateRowIdx, 1)[0];
      if (queue.some(q => q.zone === "FEEDER")) {
        openSlotDebt += MIN_ROW_GAP;
      }
      const matchingBuses = parkedBays.filter(v => getActiveBoardingColor(v) === passenger.color);
      matchingBuses.sort((a, b) => {
        if (b.seatedCount !== a.seatedCount) return b.seatedCount - a.seatedCount;
        return a.arrivalOrder - b.arrivalOrder;
      });
      const target = matchingBuses[0];
      target.seatedCount += 1;
      const isNowFull = target.seatedCount >= target.capacity;

      boarderSpawnCooldown = 0.095;
      const bayIdx = target.assignedBayIndex !== null ? target.assignedBayIndex : 1;
      const bayPos = getBayParkedWorldPos(bayIdx, target, islandBounds);
      const gateSample = sampleRoundaboutRing(passenger.pos || 0);

      for (let sub = 0; sub < CROWD_MULT; sub++) {
        const laneOffset = (sub - 1.5) * 0.35;
        const startWx = gateSample.x + gateSample.nx * laneOffset;
        const startWy = gateSample.y + gateSample.ny * laneOffset;
        const isVeryLastRunner = isNowFull && (sub === CROWD_MULT - 1);
        activeBoarders.push({
          passenger,
          col: sub,
          targetVehicleId: target.id,
          startPos: { x: startWx, y: startWy },
          targetPos: { x: bayPos.x + laneOffset * 0.28, y: bayPos.y + 0.08 },
          triggersDeparture: isVeryLastRunner,
          elapsedTime: -sub * 0.048,
          duration: 0.21
        });
      }
      updateGameHud();
    }
  }

  const stepSlots = CROWD_WALK_SPEED * effDt;
  const ringRows = queue.filter(p => p.zone === "ROUNDABOUT");
  const feederRows = queue.filter(p => p.zone === "FEEDER");

  // Record previous positions to measure each row's exact movement this frame
  for (let i = 0; i < queue.length; i++) {
    queue[i]._prevPos = queue[i].pos;
    queue[i]._prevZone = queue[i].zone;
  }

  // Keep `mergingFromFeeder` active continuously as long as `openSlotDebt > 0` OR `ringRows.length < MAX_ROUNDABOUT_ROWS`
  // so the crowd never flickers between revolving and merging in the middle of boarding a bus!
  if (feederRows.length === 0 && ringRows.length >= MAX_ROUNDABOUT_ROWS) {
    openSlotDebt = 0;
  }
  const mergingFromFeeder = (feederRows.length > 0 && (openSlotDebt > 1e-4 || ringRows.length < MAX_ROUNDABOUT_ROWS));
  if (mergingFromFeeder) {
    openSlotDebt = Math.max(0, openSlotDebt - stepSlots);
  }

  // Also check if all 18 slots on the Roundabout are full, none match the parked bay buses, and a needed color is on the Feeder Road:
  // If so, swap colors cleanly at JUNCTION_SLOT when a roundabout row passes JUNCTION_SLOT so the needed color enters the Roundabout!
  if (feederRows.length > 0 && ringRows.length >= MAX_ROUNDABOUT_ROWS && parkedBays.length > 0) {
    const activeColorsInBays = new Set(parkedBays.map(v => getActiveBoardingColor(v)));
    const ringHasMatch = ringRows.some(p => activeColorsInBays.has(p.color));
    const feederMatchIdx = feederRows.findIndex(p => activeColorsInBays.has(p.color));
    if (!ringHasMatch && feederMatchIdx !== -1) {
      const atJunction = ringRows.find(p => Math.abs(p.pos - JUNCTION_SLOT) <= 0.45);
      if (atJunction) {
        const tmpColor = atJunction.color;
        atJunction.color = feederRows[feederMatchIdx].color;
        feederRows[feederMatchIdx].color = tmpColor;
      }
    }
  }

  if (ringRows.length > 0) {
    ringRows.sort((a, b) => a.pos - b.pos);
    const L = ringRows.length;

    if (!mergingFromFeeder && L >= MAX_ROUNDABOUT_ROWS) {
      // CASE A: Roundabout is 100% FULL (all 18 slots occupied) and no one is currently merging from the Above Road.
      // All 18 rows revolve around the 360-degree Roundabout in unison at 100% constant speed `CROWD_WALK_SPEED`!
      for (let i = 0; i < L; i++) {
        ringRows[i].pos = (ringRows[i].pos - stepSlots + RING_SLOTS) % RING_SLOTS;
      }
    } else if (mergingFromFeeder) {
      // CASE B: Active 1-for-1 merge from the Above Feeder Road into `JUNCTION_SLOT (10.0)`!
      // - Main Half rows (`pos <= JUNCTION_SLOT + 0.45`) walk smoothly toward the Gate `0.0` at `CROWD_WALK_SPEED`.
      // - Return Half rows (`pos > JUNCTION_SLOT + 0.45`, on the Right Semicircle) align cleanly at `11.0, 12.0, ..., 17.0`
      //   so `JUNCTION_SLOT (10.0)` is 100% clear for the Above Feeder Road stream!
      const stopPos = JUNCTION_SLOT + MIN_ROW_GAP; // 11.0
      for (let i = 0; i < L; i++) {
        const cur = ringRows[i];
        let maxMove = stepSlots;

        if (i > 0) {
          const ahead = ringRows[i - 1];
          const distAhead = cur.pos - ahead.pos;
          maxMove = Math.min(maxMove, Math.max(0, distAhead - MIN_ROW_GAP));
        }

        if (cur.pos >= stopPos - 0.05) {
          maxMove = Math.min(maxMove, Math.max(0, cur.pos - stopPos));
        }

        cur.pos = (cur.pos - maxMove + RING_SLOTS) % RING_SLOTS;
      }
    } else {
      // CASE C: Above Feeder Road is empty (`feederRows.length === 0`) and fewer than 18 rows remain on the Roundabout.
      let headIdx = 0;
      let maxGap = -1;
      for (let i = 0; i < L; i++) {
        const ahead = ringRows[(i - 1 + L) % L];
        const gap = L === 1 ? RING_SLOTS : forwardRingDist(ringRows[i].pos, ahead.pos);
        if (gap > maxGap) {
          maxGap = gap;
          headIdx = i;
        }
      }

      for (let k = 0; k < L; k++) {
        const i = (headIdx + k) % L;
        const cur = ringRows[i];
        let maxMove = stepSlots;
        if (L > 1 && k > 0) {
          const ahead = ringRows[(i - 1 + L) % L];
          const distAhead = forwardRingDist(cur.pos, ahead.pos);
          if (distAhead < RING_SLOTS - 0.01) {
            maxMove = Math.min(maxMove, Math.max(0, distAhead - MIN_ROW_GAP));
          }
        }
        cur.pos = (cur.pos - maxMove + RING_SLOTS) % RING_SLOTS;
      }
    }
  }

  // 3. Advance the Above Feeder Road (`feederRows`) as a 100% continuous chain connected to `JUNCTION_SLOT (10.0)`!
  if (feederRows.length > 0) {
    if (mergingFromFeeder) {
      // Find the highest `pos` among Main Half rows (`pos <= JUNCTION_SLOT + 0.45`)
      let lastMainPos = -Infinity;
      for (let i = 0; i < ringRows.length; i++) {
        if (ringRows[i].pos <= JUNCTION_SLOT + 0.45 && ringRows[i].pos > lastMainPos) {
          lastMainPos = ringRows[i].pos;
        }
      }
      const distDownstream = isFinite(lastMainPos) ? (JUNCTION_SLOT - lastMainPos) : Infinity;
      const leadMinPos = Math.max(0.0, MIN_ROW_GAP - distDownstream);

      for (let i = 0; i < feederRows.length; i++) {
        const f = feederRows[i];
        const minAllowed = i === 0 ? leadMinPos : (feederRows[i - 1].pos + MIN_ROW_GAP);
        f.pos = Math.max(minAllowed, f.pos - stepSlots);
      }

      // As soon as `feederRows[0]` reaches `pos <= 0.04` AND `ringRows.length < MAX_ROUNDABOUT_ROWS`,
      // it seamlessly enters the Roundabout at `JUNCTION_SLOT (10.0)`!
      if (feederRows[0].pos <= 0.04 && ringRows.length < MAX_ROUNDABOUT_ROWS) {
        feederRows[0].zone = "ROUNDABOUT";
        feederRows[0].pos = JUNCTION_SLOT - feederRows[0].pos;
        updateGameHud();
      }
    } else {
      // Roundabout is 100% full (18 rows): keep Above Feeder Road packed continuously starting at `FEEDER_WAIT_OFFSET` (1.18)
      for (let i = 0; i < feederRows.length; i++) {
        const f = feederRows[i];
        const targetPos = FEEDER_WAIT_OFFSET + i * MIN_ROW_GAP;
        if (f.pos > targetPos) {
          f.pos = Math.max(targetPos, f.pos - stepSlots);
        } else if (f.pos < targetPos) {
          f.pos = Math.min(targetPos, f.pos + stepSlots);
        }
      }
    }
  }

  // 4. Update each of the 4 separate people (`p.members[0..3]`) in every row so they move 1-by-1 with coherent spring-lag
  //    and settle 1-by-1 into the exact same 4-wide row position (`lag = 0`) when standing!
  for (let i = 0; i < queue.length; i++) {
    const p = queue[i];
    if (!p.members) {
      p.members = [0, 1, 2, 3].map(col => ({ col, lag: 0, phaseOffset: col * 1.45 + i * 0.85 }));
    }
    let movedSlots = 0;
    if (p.zone === p._prevZone) {
      movedSlots = p.zone === "ROUNDABOUT"
        ? forwardRingDist(p._prevPos, p.pos)
        : Math.max(0, p._prevPos - p.pos);
    } else {
      movedSlots = stepSlots;
    }
    const isRowMoving = movedSlots > 1e-4;
    p.moveSpeed = effDt > 1e-5 ? (movedSlots / effDt) : 0;

    for (let col = 0; col < 4; col++) {
      const m = p.members[col];
      // When the row steps forward, each person `col = 0, 1, 2, 3` has a 1-by-1 reaction delay:
      // col 0 leads immediately, col 1 trails by 0.08 slots, col 2 by 0.16 slots, col 3 by 0.24 slots,
      // plus an independent walking stride oscillation so each person steps 1-by-1 rather than as a rigid block!
      // When the row stops, all 4 people converge 1-by-1 into `lag = 0` (the exact same aligned 4-wide position!).
      const targetLag = isRowMoving
        ? (col * 0.085 + 0.045 * Math.sin(animTime * 11.5 - col * 1.55 - i * 0.7))
        : 0.0;
      const responseRate = isRowMoving ? (14.0 - col * 2.2) : (10.5 - col * 1.8);
      m.lag += (targetLag - m.lag) * Math.min(1.0, effDt * responseRate);
    }
  }

  queue.sort((a, b) => {
    if (a.zone !== b.zone) return a.zone === "ROUNDABOUT" ? -1 : 1;
    return a.pos - b.pos;
  });
}

function checkDeadlockAndVictory() {
  if (levelState.status !== "PLAYING") return;

  const anyEnRoute = Object.values(levelState.vehicles).some(v => v.state === "EN_ROUTE");
  if (anyEnRoute || movingVehicles.size > 0 || activeBoarders.length > 0) return;

  if (levelState.passengerQueue.length > 0) {
    const parkedBays = Object.values(levelState.vehicles).filter(v => v.state === "IN_BAY" && v.seatedCount < v.capacity);
    const activeColorsInBays = new Set(parkedBays.map(v => getActiveBoardingColor(v)));
    // Since the roundabout + feeder can circulate up to 15 rows to reach a needed color, check the active window
    const searchWindow = Math.min(16, levelState.passengerQueue.length);
    for (let i = 0; i < searchWindow; i++) {
      if (activeColorsInBays.has(levelState.passengerQueue[i].color)) return;
    }
  }

  const remainingParked = Object.values(levelState.vehicles).filter(v => v.state === "PARKED").length;
  const remainingTunnels = levelState.tunnels.reduce((acc, t) => acc + t.spawnQueue.length, 0);
  const remainingInBay = Object.values(levelState.vehicles).filter(v => v.state === "IN_BAY").length;

  if (remainingParked === 0 && remainingTunnels === 0 && remainingInBay === 0 && levelState.passengerQueue.length === 0) {
    levelState.status = "VICTORY";
    if (typeof document !== "undefined" && document.getElementById("victoryModal").classList.contains("hidden")) {
      triggerVictoryModal();
    }
    return;
  }

  const unlockedBays = levelState.waitingBays.filter(b => b.isUnlocked).length;
  const occupiedBays = levelState.waitingBays.filter(b => b.isUnlocked && b.occupantVehicleId !== null).length;

  if (occupiedBays >= unlockedBays && levelState.passengerQueue.length > 0) {
    levelState.status = "DEADLOCK_RESCUE_OFFERED";
    if (typeof document !== "undefined" && document.getElementById("rescueModal").classList.contains("hidden")) {
      openRescueModal();
    }
  }
}

function triggerVictoryModal() {
  audio.playVictoryChord();
  audio.vibrate([0, 40, 50, 40, 50, 90]);

  for (let i = 0; i < 65; i++) {
    const cKey = COLOR_KEYS[i % COLOR_KEYS.length];
    confettiParticles.push({
      x: Math.random(),
      y: -0.05 - Math.random() * 0.25,
      vx: (Math.random() - 0.5) * 0.28,
      vy: 0.35 + Math.random() * 0.45,
      rot: Math.random() * 360,
      vRot: (Math.random() - 0.5) * 360,
      color: LIVERY_PALETTE[cKey].bodyTop
    });
  }

  const newStreak = profile.winStreak + 1;
  const tierInfo = TIER_INFO[levelState.difficultyTier] || TIER_INFO.NORMAL;
  const baseReward = tierInfo.baseGold;
  const availBays = levelState.waitingBays.filter(b => b.isUnlocked && b.occupantVehicleId === null).length;
  const bayBonus = Math.min(4, availBays);
  const isShuddha = levelState.powerUpsUsedCount === 0;
  const shuddhaBonus = isShuddha ? 3 : 0;
  const totalEarned = baseReward + bayBonus + shuddhaBonus;

  profile.winStreak = newStreak;
  profile.bestStreak = Math.max(profile.bestStreak, newStreak);
  profile.gold += totalEarned;
  const nextLvl = Math.min(100, levelState.levelId + 1);
  profile.currentLevel = nextLvl;
  profile.maxUnlockedLevel = Math.max(profile.maxUnlockedLevel, nextLvl);
  profile.savedMidLevelState = null;
  saveProfile();

  if (typeof document === "undefined") return;
  document.getElementById("victoryTitleText").textContent = "GREAT JOB!";
  document.getElementById("victorySubText").textContent = `Level ${levelState.levelId} Complete!`;
  document.getElementById("victoryStreakText").textContent = `${newStreak}x Win Streak Active!`;
  document.getElementById("vicBaseGold").textContent = `+${baseReward}`;
  document.getElementById("vicBayGold").textContent = `+${bayBonus}`;
  document.getElementById("vicPureLabel").textContent = isShuddha ? "No-Booster Bonus" : "Assisted Clear";
  document.getElementById("vicPureGold").textContent = `+${shuddhaBonus}`;
  document.getElementById("vicMultText").textContent = "1.0x";
  document.getElementById("vicTotalGold").textContent = `+${totalEarned} $`;

  document.getElementById("victoryModal").classList.remove("hidden");
  updateGameHud();
}

function openRescueModal() {
  audio.playBlockedBump();
  if (typeof document === "undefined") return;
  const hasVip = levelState.waitingBays.some(b => !b.isUnlocked);
  const hasInBay = Object.values(levelState.vehicles).some(v => v.state === "IN_BAY");

  document.getElementById("btnRescueVip").disabled = !(hasVip && profile.gold >= POWER_COSTS.VIP);
  document.getElementById("btnRescueMagnet").disabled = !(hasInBay && profile.gold >= POWER_COSTS.MAGNET);
  document.getElementById("rescueStreakWarning").textContent = profile.winStreak > 0
    ? `🔥 Win Streak at Risk: ${profile.winStreak}x`
    : "Unlock a bay slot or use Magnet to continue!";
  document.getElementById("rescueModal").classList.remove("hidden");
}

// ============================================================================
// 7. TACTICAL POWER-UPS & AI SOLVER HINT
// ============================================================================
function doPowerUpUndo() {
  if (historyStack.length === 0 || profile.gold < POWER_COSTS.UNDO) return;
  profile.gold -= POWER_COSTS.UNDO;
  levelState = historyStack.pop();
  resetAnimations();
  initCrowdPhysicalPositions(levelState.passengerQueue);
  audio.playPowerUpSfx();
  audio.vibrate(25);
  saveProfile();
  updateGameHud();
  showToast("↩️ Undid last dispatch");
}

function doPowerUpVipBay(specificBayIndex = null) {
  let lockedVip = null;
  if (specificBayIndex !== null && levelState.waitingBays[specificBayIndex] && !levelState.waitingBays[specificBayIndex].isUnlocked) {
    lockedVip = levelState.waitingBays[specificBayIndex];
  } else {
    lockedVip = levelState.waitingBays.find(b => !b.isUnlocked);
  }
  if (!lockedVip) return;
  if (profile.gold < POWER_COSTS.VIP) {
    showToast(`Need ${POWER_COSTS.VIP}$ to unlock extra waiting bay!`);
    return;
  }
  profile.gold -= POWER_COSTS.VIP;
  lockedVip.isUnlocked = true;
  levelState.powerUpsUsedCount += 1;
  if (levelState.status === "DEADLOCK_RESCUE_OFFERED") {
    levelState.status = "PLAYING";
  }
  if (typeof document !== "undefined") {
    document.getElementById("rescueModal").classList.add("hidden");
  }
  audio.playPowerUpSfx();
  audio.vibrate(30);
  saveProfile();
  updateGameHud();
  showToast("🅿️ Extra Waiting Bay Unlocked!");
}

function doPowerUpMagnet() {
  const inBayList = Object.values(levelState.vehicles).filter(v => v.state === "IN_BAY");
  if (inBayList.length === 0 || profile.gold < POWER_COSTS.MAGNET) return;
  inBayList.sort((a, b) => a.arrivalOrder - b.arrivalOrder);
  const target = inBayList[0];

  profile.gold -= POWER_COSTS.MAGNET;
  const needed = Math.max(0, target.capacity - target.seatedCount);
  const activeColor = getActiveBoardingColor(target);
  let pulled = 0;
  levelState.passengerQueue = levelState.passengerQueue.filter(p => {
    if (pulled < needed && p.color === activeColor) {
      pulled++;
      return false;
    }
    return true;
  });

  target.seatedCount = target.capacity;
  target.subSeatedCount = target.capacity * CROWD_MULT;
  target.state = "CLEARED";
  const bayIdx = target.assignedBayIndex;
  target.assignedBayIndex = null;
  if (bayIdx !== null && levelState.waitingBays[bayIdx]) {
    levelState.waitingBays[bayIdx].occupantVehicleId = null;
    levelState.waitingBays[bayIdx].state = "EMPTY";
  }
  levelState.powerUpsUsedCount += 1;
  if (levelState.status === "DEADLOCK_RESCUE_OFFERED") {
    levelState.status = "PLAYING";
  }

  movingVehicles.delete(target.id);
  if (typeof document !== "undefined") {
    document.getElementById("rescueModal").classList.add("hidden");
  }
  audio.playPowerUpSfx();
  audio.vibrate(45);
  saveProfile();
  updateGameHud();
  showToast("🧲 Magnet cleared bay bus!");
  checkDeadlockAndVictory();
}

function doPowerUpShuffle() {
  const parked = Object.values(levelState.vehicles).filter(v => v.state === "PARKED");
  if (parked.length <= 1 || profile.gold < POWER_COSTS.SHUFFLE) return;
  profile.gold -= POWER_COSTS.SHUFFLE;

  const byCap = {};
  parked.forEach(v => {
    byCap[v.capacity] = byCap[v.capacity] || [];
    byCap[v.capacity].push(v);
  });

  Object.values(byCap).forEach(group => {
    if (group.length <= 1) return;
    const colors = group.map(v => v.color).sort(() => Math.random() - 0.5);
    const secColors = group.map(v => v.secondaryColor).sort(() => Math.random() - 0.5);
    group.forEach((v, i) => {
      v.color = colors[i];
      v.secondaryColor = secColors[i];
      vehicleWobbles.set(v.id, { elapsed: 0, duration: 0.42, axisX: 0, axisZ: 1, amp: 0.26 });
      particlePuffs.push({
        pos: { x: v.anchorX, y: v.anchorY },
        color: LIVERY_PALETTE[v.color].bodyTop,
        elapsedTime: 0,
        duration: 0.28,
        maxRadius: 22
      });
    });
  });

  levelState.powerUpsUsedCount += 1;
  hintVehicleId = null;
  audio.playPowerUpSfx();
  audio.vibrate(30);
  saveProfile();
  updateGameHud();
  showToast("🔀 Shuffled vehicle colors!");
}

function doPowerUpAirlift() {
  const parked = Object.values(levelState.vehicles).filter(v => v.state === "PARKED");
  if (parked.length === 0 || profile.gold < POWER_COSTS.AIRLIFT) return;
  const frontColor = levelState.passengerQueue[0] ? levelState.passengerQueue[0].color : null;
  const target = parked.find(v => v.color === frontColor && !v.isMystery) || parked[0];

  profile.gold -= POWER_COSTS.AIRLIFT;
  let pulled = 0;
  const needed = target.capacity;
  levelState.passengerQueue = levelState.passengerQueue.filter(p => {
    if (pulled < needed && (p.color === target.color || p.color === target.secondaryColor)) {
      pulled++;
      return false;
    }
    return true;
  });

  target.seatedCount = target.capacity;
  target.subSeatedCount = target.capacity * CROWD_MULT;
  target.state = "CLEARED";
  target.assignedBayIndex = null;
  target.isMystery = false;
  levelState.powerUpsUsedCount += 1;

  particlePuffs.push({
    pos: { x: target.anchorX, y: target.anchorY },
    color: "#DB2777",
    elapsedTime: 0,
    duration: 0.32,
    maxRadius: 28
  });
  audio.playPowerUpSfx();
  audio.vibrate(55);
  saveProfile();
  updateGameHud();
  showToast("🚁 Airlifted bus & matching passengers!");
  checkDeadlockAndVictory();
}

function doRequestHint() {
  const traceNext = levelState.verifiedSolutionTrace.find(id => {
    const v = levelState.vehicles[id];
    return v && v.state === "PARKED" && !v.isMystery && checkRaycast(levelState, id).isClear;
  });
  const frontColor = levelState.passengerQueue[0] ? levelState.passengerQueue[0].color : null;
  const fallback = Object.values(levelState.vehicles).find(
    v => v.state === "PARKED" && !v.isMystery && v.color === frontColor && checkRaycast(levelState, v.id).isClear
  ) || Object.values(levelState.vehicles).find(
    v => v.state === "PARKED" && !v.isMystery && checkRaycast(levelState, v.id).isClear
  );

  const chosenId = traceNext || (fallback ? fallback.id : null);
  if (chosenId) {
    hintVehicleId = chosenId;
    vehicleWobbles.set(chosenId, { elapsed: 0, duration: 0.45, axisX: 0, axisZ: 1, amp: 0.22 });
    audio.playPowerUpSfx();
    audio.vibrate(15);
    showToast("💡 Best next bus highlighted!");
  } else {
    showToast("No unblocked vehicles found!");
  }
}
